def stockSpans(prices: list[int]) -> list[int]:
    stack = []
    spans = []
    for p in prices:
        span = 1
        while stack and stack[-1][0] <= p:
            span += stack.pop()[1]
        stack.append((p, span))
        spans.append(span)
    return spans

